using System.Text.Json.Nodes;
using PowerShapeMcp;
internal static class SurfaceSetPartialStopCheck
{
 internal static int LiveProof(string root,string reference,string output){var r=JsonNode.Parse(File.ReadAllText(reference))!.AsObject();var reply=SolidScaleProof.Raw(root,r["requestId"]!.GetValue<string>()).Value;SurfaceSetPartialStopProof.Check(root,reply,r["parameters"]!.AsObject(),true);File.WriteAllText(output,new JsonObject{["state"]="passed",["originalNativeResponseOnly"]=true,["cadConnectionAttempted"]=false}.ToJsonString());Console.WriteLine("PASS original Native partial observation revalidated offline; no IPC/CAD.");return 0;}
 internal static int Origin(string root,string id,string sha,string output){var h=SurfaceSetPartialStopProof.Origin(root,id,sha);Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(output))!);File.WriteAllText(output,new JsonObject{["state"]="passed",["actualOriginalPartialHistory"]=true,["artifactCount"]=h.Pins.Count,["copyId"]=h.Plan["copyId"]!.DeepClone(),["cadConnectionAttempted"]=false}.ToJsonString(new(){WriteIndented=true}));Console.WriteLine($"PASS: actual original partial set history ({h.Pins.Count} artifacts) checked in SDK; no CAD.");return 0;}
 internal static int Run(string input,string output){var report=JsonNode.Parse(File.ReadAllText(input))!.AsObject();var f=report["fixture"]!.AsObject();string root=f["root"]!.GetValue<string>(),id=f["originalExecutionId"]!.GetValue<string>(),sha=f["originalExecutionSha256"]!.GetValue<string>();var history=SurfaceSetPartialStopProof.Origin(root,id,sha);var reply=SolidScaleProof.Raw(root,f["observationId"]!.GetValue<string>(),f["observationSha256"]!.GetValue<string>()).Value;int cases=1;
  var first=history.Plan["targetEntityKeys"]![0]!.AsArray();var original=history.Plan["captureBefore"]!.AsObject();var current=reply["captureObserved"]!.AsObject();var vector=history.Plan["vectorRaw"]!.AsArray();var good=SurfaceSetPartialStopProof.Compare(history.Source,reply["after"]!.AsObject(),original,current,first,vector);if(!JsonNode.DeepEquals(good,reply["comparisonObserved"]))throw new InvalidDataException("Actual Native/SDK partial comparison differs.");cases++;
  foreach(var fault in new[]{"target_normal","other_tiny_normal","other_position","visibility","zero_normal"}){var changed=current.DeepClone().AsObject();var rows=changed["witnesses"]!.AsArray();if(fault=="target_normal")rows[0]!["samples"]!["normalsWorldRaw"]![0]![0]=0.01;if(fault=="other_tiny_normal")rows[2]!["samples"]!["normalsWorldRaw"]![0]![0]=2.220446049250313e-16;if(fault=="other_position")rows[2]!["samples"]!["positionsWorldRaw"]![0]![0]=999;if(fault=="visibility")rows[0]!["samples"]!["visibility"]![0]=false;if(fault=="zero_normal")rows[0]!["samples"]!["normalsWorldRaw"]![0]=new JsonArray(0,0,0);bool rejected=false;try{SurfaceSetPartialStopProof.Compare(history.Source,reply["after"]!.AsObject(),original,changed,first,vector);}catch(ReferenceRejected){rejected=true;}if(!rejected)throw new InvalidDataException("SDK admitted partial witness fault "+fault);cases++;}
  var summary=reply["comparisonObserved"]!.AsObject().DeepClone().AsObject();summary["firstTargetMaxNormalDifferenceRaw"]=1.1102230246251565e-16;SurfaceSetPartialStopProof.Summary(good,summary,original,current);cases++;
  summary["firstTargetMaxNormalDifferenceRaw"]=9e-13;bool badSummary=false;try{SurfaceSetPartialStopProof.Summary(good,summary,original,current);}catch(ReferenceRejected){badSummary=true;}if(!badSummary)throw new InvalidDataException("Forged error summary admitted.");cases++;
  var qualified=reply.DeepClone().AsObject();qualified["nativeProviderQualified"]=true;string testId=Guid.NewGuid().ToString("N");qualified["bridgeRequestId"]=testId;File.WriteAllText(Path.Combine(root,"responses",testId+".json"),qualified.ToJsonString());SurfaceSetPartialStopProof.Check(root,qualified,f["arguments"]!.AsObject(),true);cases++;
  bool refused=false;try{SurfaceSetPartialStopProof.Check(root,reply,f["arguments"]!.AsObject());}catch(ReferenceRejected){refused=true;}if(!refused)throw new InvalidDataException("Fake Native context issued qualified partial observation.");cases++;
  Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(output))!);File.WriteAllText(output,new JsonObject{["state"]="passed",["cases"]=cases,["cadConnectionAttempted"]=false}.ToJsonString(new(){WriteIndented=true}));Console.WriteLine($"PASS: {cases} actual Framework/SDK partial history, numeric target, exact nontarget and unqualified-context checks; no CAD.");return 0;
 }
}
